  Canvas KeyboardLeverGesture(int direction){var icon=new Canvas{Width=34,Height=38};icon.Children.Add(new Rectangle{Width=24,Height=34,Stroke=muted,StrokeThickness=2,Margin=new Thickness(4,2,0,0)});icon.Children.Add(new Line{X1=6,Y1=13,X2=26,Y2=13,Stroke=muted,StrokeThickness=2});icon.Children.Add(new Line{X1=6,Y1=25,X2=26,Y2=25,Stroke=muted,StrokeThickness=2});if(direction==1){icon.Children.Add(new Ellipse{Width=14,Height=14,Fill=text,Margin=new Thickness(10,12,0,0)});}else icon.Children.Add(new Polygon{Fill=text,Points=direction==0?new PointCollection(new[]{new Point(16,4),new Point(7,15),new Point(12,15),new Point(12,29),new Point(20,29),new Point(20,15),new Point(25,15)}):new PointCollection(new[]{new Point(16,34),new Point(7,23),new Point(12,23),new Point(12,9),new Point(20,9),new Point(20,23),new Point(25,23)})});return icon;}
  UIElement KeyboardHorizontalChoices(Panel choices,double step,int selected){var grid=new Grid();grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});grid.ColumnDefinitions.Add(new ColumnDefinition());grid.ColumnDefinitions.Add(new ColumnDefinition{Width=GridLength.Auto});var viewer=new ScrollViewer{Content=choices,HorizontalScrollBarVisibility=ScrollBarVisibility.Hidden,VerticalScrollBarVisibility=ScrollBarVisibility.Disabled};Grid.SetColumn(viewer,1);grid.Children.Add(viewer);var left=Button("‹",()=>viewer.ScrollToHorizontalOffset(Math.Max(0,viewer.HorizontalOffset-step)));var right=Button("›",()=>viewer.ScrollToHorizontalOffset(viewer.HorizontalOffset+step));foreach(var button in new[]{left,right}){button.Width=18;button.Height=72;button.Padding=new Thickness(0);button.BorderThickness=new Thickness(0);button.Background=Brushes.Transparent;button.Margin=new Thickness(0);button.FontSize=20;}Grid.SetColumn(right,2);grid.Children.Add(left);grid.Children.Add(right);bool positioned=false;viewer.ScrollChanged+=(s,e)=>{left.Visibility=viewer.HorizontalOffset>0?Visibility.Visible:Visibility.Collapsed;right.Visibility=viewer.HorizontalOffset<viewer.ScrollableWidth?Visibility.Visible:Visibility.Collapsed;if(!positioned&&viewer.ViewportWidth>0&&viewer.ExtentWidth>0){positioned=true;if(selected>=0)viewer.ScrollToHorizontalOffset(Math.Max(0,(selected+1)*step-viewer.ViewportWidth));}};return grid;}
  sealed class KeyboardViewCommand {public string Token,Setting;public object Value;}
  List<KeyboardViewCommand> KeyboardViewCommands(string scope,Dictionary<string,object> state,KeyboardViewsDraft draft){var result=new List<KeyboardViewCommand>();foreach(string token in draft.Dirty.Where(key=>key.StartsWith(scope,StringComparison.Ordinal)).OrderBy(key=>key.EndsWith("Mode",StringComparison.Ordinal)?1:0)){string setting=token;object value=null;if(token=="leverMode"){if(!draft.LeverMode.HasValue||!new[]{0,1,2,3,4,7}.Contains(draft.LeverMode.Value))throw new ArgumentException("拨杆模式无效。");value=draft.LeverMode.Value;}else if(token=="oledMode"){if(!draft.OledMode.HasValue||!KeyboardOledModes.Contains(draft.OledMode.Value))throw new ArgumentException("OLED 模式无效。");value=draft.OledMode.Value;}else if(token=="oledPreset"){if(!draft.OledPreset.HasValue||draft.OledPreset<0||draft.OledPreset>5)throw new ArgumentException("OLED 预设无效。");value=draft.OledPreset.Value;}else if(token=="oledBrightness"){if(!draft.OledBrightness.HasValue||draft.OledBrightness<0||draft.OledBrightness>100)throw new ArgumentException("OLED 亮度无效。");value=draft.OledBrightness.Value;}else if(token=="oledEnabled"||token=="oledKpsEnabled"){bool? enabled=token=="oledEnabled"?draft.OledEnabled:draft.OledKpsEnabled;if(!enabled.HasValue)throw new ArgumentException("OLED 开关尚未确认。");value=enabled.Value;}else if(token.StartsWith("leverBinding:",StringComparison.Ordinal)){string source=token.Substring("leverBinding:".Length),target;if(!new[]{"LeverUp","LeverMid","LeverDown"}.Contains(source)||!GearOptions(state,"keySources").Contains(source)||!draft.LeverBindings.TryGetValue(source,out target)||!GearOptions(state,"keyTargets").Contains(target))throw new ArgumentException("拨杆按键功能无效。");setting="keyBinding";value=new Dictionary<string,object>{{"source",source},{"target",target}};}else if(token.StartsWith("leverFlag:",StringComparison.Ordinal)||token.StartsWith("oledFlag:",StringComparison.Ordinal)){bool lever=token.StartsWith("lever",StringComparison.Ordinal);string key=token.Substring(token.IndexOf(':')+1);int mode;bool? enabled;var flags=lever?draft.LeverFlags:draft.OledFlags;if(!Int32.TryParse(key,out mode)||!(lever?new[]{0,1,2,3,4,7}:KeyboardOledModes).Contains(mode)||!flags.TryGetValue(key,out enabled)||!enabled.HasValue)throw new ArgumentException("显示功能开关无效。");setting=lever?"leverModeEnabled":"oledModeEnabled";value=new Dictionary<string,object>{{"mode",mode},{"enabled",enabled.Value}};}else if(token.StartsWith("oledBar:",StringComparison.Ordinal)){string item=token.Substring(8);bool? enabled;if(!GearOptions(state,"oledBarItems").Contains(item)||!draft.OledIndicators.TryGetValue(item,out enabled)||!enabled.HasValue)throw new ArgumentException("OLED 状态项目无效。");setting="oledBarItem";value=new Dictionary<string,object>{{"item",item},{"enabled",enabled.Value}};}else throw new ArgumentException("未知编辑项目。");if(!GearCanSet(state,setting))throw new ArgumentException("此设置当前不可用。");result.Add(new KeyboardViewCommand{Token=token,Setting=setting,Value=value});}return result;}
  async Task ApplyKeyboardViewDraftAsync(string scope,Dictionary<string,object> state,KeyboardViewsDraft draft){if(!KeyboardViewMayApply(scope,state,draft))return;List<KeyboardViewCommand> commands;try{commands=KeyboardViewCommands(scope,state,draft);}catch(ArgumentException error){Log(error.Message);return;}keyboardViewsApplying=true;try{ShowPage(page);foreach(var command in commands){Dictionary<string,object> current;if(!gearStates.TryGetValue("keyboard",out current)||OriginalStateText(current,"deviceId","")!=draft.DeviceId||!CanApplyGear(current,command.Setting))break;await SetGearSetting("keyboard",current,command.Setting,command.Value);Dictionary<string,object> after;if(!gearStates.TryGetValue("keyboard",out after)||Object.ReferenceEquals(current,after)||OriginalStateFlag(after,"writeConfirmed")!=true)break;draft.Dirty.Remove(command.Token);}}finally{keyboardViewsApplying=false;if(!closing)ShowPage(page);}}
 }
